#!/usr/bin/env bash
# pvetheme @MBVER@: Marleybop themes for Proxmox VE. Self-contained installer (generated by build.sh, do not edit).
#
#   install:    bash install.sh            (or: curl -fsSL <url>/install.sh | bash)
#   uninstall:  bash install.sh uninstall  (or: pvetheme uninstall)
#
# What it does on the node, all undone by "uninstall":
#   - unpacks the theme engine to /usr/local/share/pvetheme and links /usr/local/sbin/pvetheme to it
#   - writes one theme-*.css per theme, 5 font files and marleybop-theme.js into
#     /usr/share/javascript/proxmox-widget-toolkit/themes/
#   - adds the themes to proxmoxlib.js (Color Theme list) and a script tag to index.html.tpl
#   - adds an apt hook that repeats those two edits after a Proxmox update
#   - reloads pveproxy
# Nothing is downloaded: everything is inside this file.
set -euo pipefail

main() {
    local share=/usr/local/share/pvetheme
    local bin=/usr/local/sbin/pvetheme
    local etc=/etc/pvetheme
    local want=@MBSUM@
    local cmd=${1:-install}

    [ "$(id -u)" = 0 ] || { echo "error: run this as root (on the Proxmox node itself)" >&2; exit 1; }

    case "$cmd" in
        uninstall|status|list)
            if [ -x "$bin" ]; then exec "$bin" "$@"; fi
            echo "pvetheme is not installed on this node."; exit 0 ;;
        install) ;;
        *) echo "usage: install.sh [install [--default <name> | --no-default] | uninstall | status | list]" >&2; exit 1 ;;
    esac

    for tool in base64 tar gzip sha256sum sed awk; do
        command -v "$tool" >/dev/null 2>&1 || { echo "error: $tool is needed but not installed" >&2; exit 1; }
    done

    local tmp got
    tmp=$(mktemp -d)
    # expanded now on purpose: tmp is local to main and gone when the trap runs
    # shellcheck disable=SC2064
    trap "rm -rf '$tmp'" EXIT
    payload | base64 -d > "$tmp/payload.tgz"
    got=$(sha256sum "$tmp/payload.tgz" | cut -d' ' -f1)
    [ "$got" = "$want" ] || { echo "error: the installer is damaged or incomplete (checksum mismatch). Download it again." >&2; exit 1; }

    # Versions 1 and 2 were installed under the name marleybop-pve-theme: take them out cleanly,
    # keeping the default theme and any themes made on this node.
    local old=/usr/local/sbin/marleybop-pve-theme oldetc=/etc/marleybop-pve-theme
    if [ -x "$old" ]; then
        mkdir -p "$etc/themes"
        if [ -f "$oldetc/default" ] && [ ! -f "$etc/default" ]; then
            case "$(cat "$oldetc/default")" in 0) echo none ;; 1) echo marleybop-auto ;; *) cat "$oldetc/default" ;; esac > "$etc/default"
        fi
        cp -n "$oldetc"/themes/*.theme "$etc/themes/" 2>/dev/null || true
        MB_NO_RELOAD=1 "$old" uninstall >/dev/null 2>&1 || true
        rm -rf "$oldetc" /usr/local/share/marleybop-pve-theme "$old" /etc/apt/apt.conf.d/99marleybop-pve-theme
        echo "Moved the earlier install (marleybop-pve-theme) over to pvetheme."
    fi

    mkdir -p "$tmp/x"
    tar -xzf "$tmp/payload.tgz" -C "$tmp/x" --no-same-owner
    rm -rf "$share"
    mkdir -p "$share" "$(dirname "$bin")"
    cp -R "$tmp/x/." "$share/"
    chmod -R u=rwX,go=rX "$share"
    chmod 0755 "$share/apply.sh"
    ln -sfn "$share/apply.sh" "$bin"

    shift || true
    "$bin" install "$@"
}

payload() {
    cat <<'__MARLEYBOP_PAYLOAD__'
